];


export function MediaExplorer({
  project,
  statusByPath,
  sdJobs,
  xttsJobs,
  extraPaths,
  advancedMediaUsages = null,
  onImportStories,
  onImportMedia,
  onImportMediaFolder,
  onSelectNode,
  onRevealGraphNode,
  mediaTags = {},
  onAddMediaTag,
  onRemoveMediaTag,
  onDeleteMedia,
  onMediaCatalogChanged,
  workspaceDir = '',
  savePath,
  projectName = '',
  onMediaCreated,
  mediaToolRequest = null,
  onAcknowledgeMediaToolRequest,
  onInvalidateMediaToolRequest,
  onValidateMediaToolRequest,
  onApplyMediaToolProjectAction,
