import { createPortal } from 'react-dom';
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { useLocalFile } from '../../hooks/useLocalFile';
import { createAudioPlayer, disposeAudioPlayerRef } from '../../utils/audioPlayer';
import { Button } from '../common/Button';
import { FilePen, Scissors } from '../icons/LucideLocal';
import { resolveUsageTarget } from './usageTarget';
import './MediaPopover.css';

function fmt(secs) {
  if (!Number.isFinite(secs) || secs < 0) return '--:--';
  const s = Math.floor(secs);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

function waveHeights(name, bars = 28) {
  const heights = [];
  for (let i = 0; i < bars; i++) {
    const c = name.charCodeAt(i % name.length) || 65;
    heights.push(4 + ((c * 7 + i * 13) % 14));
  }
  return heights;
}

function tagHue(name) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = ((h * 31) + name.charCodeAt(i)) >>> 0;
  return (h * 137.5) % 360;
}
function tagStyle(name) {
  return { background: `hsl(${Math.round(tagHue(name))},55%,45%)`, color: '#fff' };
}

function PopoverAudioPlayer({ path, name }) {
  const [playing, setPlaying] = useState(false);
  const [current, setCurrent] = useState(0);
  const [duration, setDuration] = useState(null);
  const audioRef = useRef(null);
  const url = useLocalFile(path);
  const heights = waveHeights(name);
  const progress = duration ? Math.min(1, current / duration) : 0;

  useEffect(() => {
    if (!url) return undefined;
    const a = createAudioPlayer(url);
    audioRef.current = a;
    const onPlay = () => setPlaying(true);
    const onPause = () => setPlaying(false);
    const onEnded = () => {
      setPlaying(false);
      setCurrent(0);
    };
    const onTimeUpdate = () => setCurrent(a.currentTime);
    const onDurationChange = () => setDuration(a.duration);
    a.addEventListener('play', onPlay);
    a.addEventListener('pause', onPause);
    a.addEventListener('ended', onEnded);
    a.addEventListener('timeupdate', onTimeUpdate);
    a.addEventListener('durationchange', onDurationChange);
    a.play().catch(() => {});
    return () => disposeAudioPlayerRef(audioRef);
  }, [url]);

  function toggle() {
    const a = audioRef.current;
    if (!a) return;
    if (playing) { a.pause(); } else { a.play().catch(() => {}); }
  }

  function handleWaveClick(e) {
    const a = audioRef.current;
    if (!a || !duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = (e.clientX - rect.left) / rect.width;
    a.currentTime = ratio * duration;
  }

  return (
    <div className="mp-audio-player">
      <div className="mp-waveform" onClick={handleWaveClick} title="Cliquer pour chercher">
        {heights.map((h, i) => (
          <span
            key={i}
            className={`mp-wave-bar${i / heights.length < progress ? ' is-played' : ''}`}
            style={{ height: h }}
          />
        ))}
        <div className="mp-waveform-progress" style={{ width: `${progress * 100}%` }} />
      </div>
      <div className="mp-transport">
        <button className="mp-play-btn" type="button" onClick={toggle} title={playing ? 'Pause' : 'Lire'}>
          {playing ? '⏸' : '▶'}
        </button>
        <span className="mp-timer">{fmt(current)} / {duration != null ? fmt(duration) : '--:--'}</span>
      </div>
    </div>
  );
}

function TagEditor({ path, itemTags, allProjectTags, onAddMediaTag, onRemoveMediaTag }) {
  const [newTag, setNewTag] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    const t = newTag.trim();
    if (t) { onAddMediaTag(path, t); setNewTag(''); }
  }

  return (
    <div className="mp-tag-section">
      <div className="mp-tag-chips">
        {itemTags.map((tag) => (
          <span key={tag} className="mp-tag-chip" style={tagStyle(tag)}>
            {tag}
            <button
              type="button"
              className="mp-tag-remove"
              onClick={() => onRemoveMediaTag(path, tag)}
              title={`Retirer le tag "${tag}"`}
            >×</button>
          </span>
        ))}
        {allProjectTags.filter((t) => !itemTags.includes(t)).map((tag) => (
          <button
            key={tag}
            type="button"
            className="mp-tag-available"
            style={{ borderColor: tagStyle(tag).background, color: tagStyle(tag).background }}
            onClick={() => onAddMediaTag(path, tag)}
            title={`Ajouter le tag "${tag}"`}
          >
            + {tag}
          </button>
        ))}
      </div>
      <form className="mp-tag-form" onSubmit={handleSubmit}>
        <input
          className="mp-tag-input"
          value={newTag}
          onChange={(e) => setNewTag(e.target.value)}
          placeholder="+ Nouveau tag"
          onKeyDown={(e) => e.stopPropagation()}
        />
      </form>
    </div>
  );
}

export function MediaPopover({
  item, anchorRect, getMeta, onSelectNode, onRevealGraphNode, onClose,
  itemTags = [], allProjectTags = [], onAddMediaTag, onRemoveMediaTag, onSplit, onEditImage,
}) {
  const popRef = useRef(null);
  const imageUrl = useLocalFile(item.kind === 'image' ? item.path : null);
  const meta = getMeta ? getMeta(item.path) : null;
  const [pos, setPos] = useState(null);

  // Calculate position after first paint (needs rendered dimensions)
  useLayoutEffect(() => {
    const pop = popRef.current;
    if (!pop || !anchorRect) return;
    const { width: pw, height: ph } = pop.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let left = anchorRect.left + anchorRect.width / 2 - pw / 2;
    let top = anchorRect.top - ph - 10;
    if (top < 8) top = anchorRect.bottom + 10;
    left = Math.max(8, Math.min(vw - pw - 8, left));
    top = Math.max(8, Math.min(vh - ph - 8, top));
    setPos({ left, top });
  }, [anchorRect]);

  useEffect(() => {
    function onKey(e) { if (e.key === 'Escape') onClose(); }
    function onDown(e) {
      if (popRef.current && !popRef.current.contains(e.target)) onClose();
    }
    document.addEventListener('keydown', onKey, true);
    document.addEventListener('pointerdown', onDown, true);
    return () => {
      document.removeEventListener('keydown', onKey, true);
      document.removeEventListener('pointerdown', onDown, true);
    };
  }, [onClose]);

  const usageTarget = resolveUsageTarget(item, { onSelectNode, onRevealGraphNode });
  const canGoTo = Boolean(usageTarget);

  function handleGoTo() {
    usageTarget?.go();
    onClose();
  }

  // Une étiquette est posée **sur un chemin**. Une référence du document sans
  // fichier lié n'en a pas : offrir le geste le rendrait silencieusement sans
  // effet, ce qui est pire que de ne pas l'offrir.
  const hasTagActions = Boolean(onAddMediaTag && onRemoveMediaTag && item.path);

  const style = pos
    ? { position: 'fixed', left: pos.left, top: pos.top, opacity: 1 }
    : { position: 'fixed', left: -9999, top: -9999, opacity: 0 };

  return createPortal(
    <div ref={popRef} className="media-popover" style={style} role="dialog" aria-modal="true">
      <div className="mp-header">
        <span className="mp-filename" title={item.path}>{item.name}</span>
        <button className="mp-close-btn" type="button" onClick={onClose} title="Fermer">×</button>
      </div>

      {item.kind === 'image' && (
        <>
          <div className="mp-image-preview">
            {imageUrl
              ? <img src={imageUrl} alt={item.name} draggable={false} />
              : <div className="mp-image-placeholder" />}
          </div>
          {meta?.width ? (
            <div className="mp-meta-row">{meta.width} × {meta.height} px</div>
          ) : null}
          {item.exists && onEditImage ? (
            <Button
              className="mp-action-btn"
              onClick={() => {
                onClose();
                onEditImage(item);
              }}
            >
              <FilePen width={14} height={14} strokeWidth={2} absoluteStrokeWidth />
              Modifier l’image…
            </Button>
          ) : null}
        </>
      )}

      {item.kind === 'audio' && (
        <>
          <PopoverAudioPlayer path={item.path} name={item.name} />
          {canGoTo ? (
            <Button
              className="mp-action-btn mp-action-btn--goto"
              onClick={handleGoTo}
              title={`Ouvrir les réglages de « ${usageTarget.label} »`}
            >
              Voir l’utilisation dans le projet
            </Button>
          ) : null}
          {onSplit ? (
            <Button
              className="mp-action-btn"
              onClick={() => {
                onClose();
                onSplit(item);
              }}
            >
              <Scissors width={14} height={14} strokeWidth={2} absoluteStrokeWidth />
              Découper un audio
            </Button>
          ) : null}
        </>
      )}

      {hasTagActions && (
        <>
          <div className="mp-sep" />
          <TagEditor
            path={item.path}
            itemTags={itemTags}
            allProjectTags={allProjectTags}
            onAddMediaTag={onAddMediaTag}
            onRemoveMediaTag={onRemoveMediaTag}
          />
        </>
      )}
    </div>,
    document.body,
  );
}

sources.src/components/MediaExplorer/MediaSelect:
import { tagStyle } from './helpers';
import { Button } from '../common/Button';

export function MediaSelectionBar({
  selectedCount,
  graphMediaTarget,
  onAssignToGraph,
  selectedAudioItems,
  onCopyAudio,
  onCutAudio,
  onOpenAssembly,
  onAddMediaTag,
  bulkTag,
  onBulkTagChange,
  bulkTagOpen,
  onBulkTagOpenChange,
  allTags,
  visibleSelectedItems,
  onClear,
}) {
  const multiple = selectedCount > 1;
  if (!multiple && !(selectedCount === 1 && graphMediaTarget)) return null;

  function applyBulkTag(e) {
    e.preventDefault();
    const tag = bulkTag.trim();
    if (!tag || selectedCount === 0 || !onAddMediaTag) return;
    for (const item of visibleSelectedItems) {
      onAddMediaTag(item.path, tag);
    }
    onBulkTagChange('');
  }

  return (
    <div className="media-selection-bar">
      <span className="media-selection-count">{selectedCount} sélectionné{selectedCount > 1 ? 's' : ''}</span>
      {graphMediaTarget && (
        <Button variant="primary" className="media-selection-btn" onClick={onAssignToGraph}>
          Utiliser sur « {graphMediaTarget.label} »
        </Button>
      )}
      {multiple && selectedAudioItems.length > 0 ? (
        <>
          <Button className="media-selection-btn" onClick={onCopyAudio}>
            Copier {selectedAudioItems.length} son{selectedAudioItems.length > 1 ? 's' : ''}
          </Button>
          <Button className="media-selection-btn" onClick={onCutAudio}>
            Couper {selectedAudioItems.length} son{selectedAudioItems.length > 1 ? 's' : ''}
          </Button>
          {selectedAudioItems.length >= 2 && (
            <Button variant="primary" className="media-selection-btn" onClick={onOpenAssembly}>
              Assembler les audios
            </Button>
          )}
        </>
      ) : null}
      {multiple && onAddMediaTag ? (
        <div className="media-selection-tag-wrap">
          <form className="media-selection-tag-form" onSubmit={applyBulkTag}>
            <input
              className="media-selection-tag-input"
              value={bulkTag}
              onChange={(e) => onBulkTagChange(e.target.value)}
              onFocus={() => onBulkTagOpenChange(true)}
              onBlur={() => setTimeout(() => onBulkTagOpenChange(false), 150)}
              placeholder="+ Tag commun"
            />
            <Button type="submit" className="media-selection-btn" disabled={!bulkTag.trim()}>
              Appliquer
            </Button>
          </form>
          {bulkTagOpen && allTags.length > 0 && (
            <div className="media-tag-suggestions">
              {allTags
                .filter((t) => !bulkTag || t.toLowerCase().includes(bulkTag.toLowerCase()))
                .map((tag) => (
                  <button
                    key={tag}
                    type="button"
                    className="media-tag-suggestion-item"
                    onMouseDown={(e) => {
                      e.preventDefault();
                      for (const item of visibleSelectedItems) onAddMediaTag(item.path, tag);
                      onBulkTagChange('');
                      onBulkTagOpenChange(false);
                    }}
                  >
                    <span className="me-tag-chip" style={tagStyle(tag)}>{tag}</span>
                  </button>
                ))}
            </div>
          )}
        </div>
      ) : null}
      {multiple && <Button className="media-selection-btn" onClick={onClear}>Effacer</Button>}
    </div>
  );
}

import { useLocalFile } from '../../hooks/useLocalFile';
import { AudioWave } from './AudioWave';
import { KindIcon } from './KindIcon';

export function MediaThumb({ item, compact }) {
  const imageUrl = useLocalFile(item.kind === 'image' && item.exists ? item.path : null);
  if (imageUrl) return <img className="media-thumb-img" src={imageUrl} alt="" draggable={false} />;
  if (item.kind === 'audio') {
    return (
      <div className="media-thumb-fallback is-audio">
        <AudioWave name={item.name} bars={compact ? 8 : 18} />
      </div>
    );
  }
  return (
    <div className={`media-thumb-fallback is-${item.kind}`}>
      <KindIcon kind={item.kind} />
    </div>
  );
}

