import { Button } from '../common/Button';

export function MediaToolResultBanner({
  result,
  unavailableReason = '',
  onFinish,
}) {
  if (!result) return null;
  const createdCount = result.createdPaths?.length ?? 0;
  const defaultMessage = createdCount === 1
    ? 'Le fichier créé est sélectionné dans Médias.'
    : `${createdCount} fichiers créés sont sélectionnés dans Médias.`;

  return (
    <div className="media-tool-result" role="status" aria-live="polite">
      <Button
        variant="icon"
        className="media-tool-result-close"
        onClick={onFinish}
        aria-label="Fermer la notification"
        title="Fermer"
      >×</Button>
      <div className="media-tool-result-copy">
        <strong>{result.projectApplied ? 'Projet mis à jour' : 'Fichiers créés dans Médias'}</strong>
        <span>{result.message || defaultMessage}</span>
        {unavailableReason ? (
          <small>{unavailableReason}{result.projectApplied ? '' : ' Les fichiers créés restent disponibles dans Médias.'}</small>
        ) : null}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { tagStyle } from './helpers';
import { selectionTagStates } from '../../store/mediaTags';

export function TagSection({ paths, mediaTags, itemTags, allProjectTags, onAddMediaTag, onRemoveMediaTag }) {
  const [newTag, setNewTag] = useState('');
  const targetPaths = (paths ?? []).filter(Boolean);
  const isBulk = targetPaths.length > 1;

  // La lecture du panneau est celle de `store/mediaTags.js`, et elle voit tous
  // les alias d'un même fichier : un chemin se présente ici en forme native ou
  // en `/` selon le champ d'où il vient, et une carte héritée peut porter les
  // deux. Afficher la première entrée seule contredirait la vignette, et un
  // retrait laisserait survivre l'étiquette de l'autre alias.
  const states = selectionTagStates(mediaTags, targetPaths, allProjectTags, itemTags);

  function handleSubmit(e) {
    e.preventDefault();
    const t = newTag.trim();
    if (t) {
      for (const path of targetPaths) onAddMediaTag(path, t);
      setNewTag('');
    }
  }

  return (
    <div className="ctx-tag-section">
      <div className="ctx-tag-header">{isBulk ? `Tags (${targetPaths.length})` : 'Tags'}</div>
      {states.map(({ tag, active, partial }) => (
        <button
          key={tag}
          type="button"
          className={`ctx-tag-toggle${partial ? ' is-partial' : ''}`}
          onClick={() => {
            for (const path of targetPaths) {
              if (active) onRemoveMediaTag(path, tag);
              else onAddMediaTag(path, tag);
            }
          }}
        >
          <span className="ctx-tag-check">{active ? '✓' : partial ? '–' : ''}</span>
          <span className="me-tag-chip" style={tagStyle(tag)}>{tag}</span>
        </button>
      ))}
      <form className="ctx-tag-new-form" onSubmit={handleSubmit}>
        <input
          className="ctx-tag-new-input"
          value={newTag}
          onChange={(e) => setNewTag(e.target.value)}
          placeholder="+ Nouveau tag"
          onKeyDown={(e) => e.stopPropagation()}
        />
      </form>
    </div>
  );
}

// Le badge d'usage d'un média. `known` à faux n'est pas « zéro » : c'est
// « on ne sait pas ». Afficher ×0 dans ce cas serait une affirmation, et un
// auteur supprime un fichier sur la foi d'un ×0.
export function UsageBadge({ count, known = true }) {
  if (!known) {
    return (
      <span
        className="media-usage-badge is-unknown"
        title="Usages non calculés : ouvre l’éditeur du projet pour les établir."
      >?</span>
    );
  }
  return <span className={`media-usage-badge${count === 0 ? ' is-zero' : ''}`}>×{count}</span>;
}

