import { presentStoredError } from '../../i18n/userMessage.js';
import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';
import { useEffect, useRef, useState } from 'react';
import './MediaSubscriptionsPanel.css';

function sourceLabel(source) {
  return source === 'youtube' ? 'YouTube' : source === 'podcast' ? 'Podcast' : source || 'Source';
}

function notificationLabel(notification) {
  const count = Number(notification.count) || 0;
  if (notification.source === 'youtube') return `${count} ${count === 1 ? 'nouvelle vidéo' : 'nouvelles vidéos'}`;
  return `${count} ${count === 1 ? 'nouvel épisode' : 'nouveaux épisodes'}`;
}

// Pause (choix de l'utilisateur) et projet introuvable (état constaté) sont
// deux informations distinctes, affichées ensemble si besoin.
function subscriptionStateLabel(subscription) {
  const state = subscription.enabled ? 'Actif' : 'Suspendu';
  return subscription.status === 'missing' ? `${state} · Projet introuvable` : state;
}

function YoutubeToolsNotice({ tools, onUpdate }) {
  const action = tools.missing ? 'Installer' : 'Mettre à jour';
  return (
    <div className="media-subscriptions-tools">
      <p>{tools.missing ? 'L’outil YouTube n’est pas installé.' : 'L’outil YouTube peut être mis à jour.'}</p>
      <button type="button" onClick={() => onUpdate?.()} disabled={tools.updating}>
        {tools.updating ? 'Mise à jour…' : action}
      </button>
      {tools.error && <p className="media-subscriptions-error" role="alert">{tools.error}</p>}
    </div>
  );
}

function triggerLabel(count) {
  return count > 0 ? `${count} notification${count > 1 ? 's' : ''}` : 'Notifications';
}

export function MediaSubscriptionsPanel({
  subscriptions = [],
  notifications = [],
  checking = false,
  onCheck,
  onOpenNotification,
  onDismissNotification,
  onToggleSubscription,
  onRemoveSubscription,
  onRelocateSubscription,
  toast,
  onCloseToast,
  storageError = null,
  youtubeTools = null,
  onUpdateTools,
  home = true,
}) {
  useMessageLanguage();
  const [open, setOpen] = useState(false);
  const trigger = useRef(null);
  // Un suivi suspendu doit garder son accès à la gestion pour pouvoir être repris.
  const visible = subscriptions.length > 0 || notifications.length > 0 || Boolean(storageError);
  const count = notifications.length;

  useEffect(() => {
    if (!home) setOpen(false);
  }, [home]);

  function closePanel() {
    setOpen(false);
    trigger.current?.focus();
  }

  // Écouté sur le conteneur : Échap ferme aussi depuis le bouton, où reste le
  // focus juste après l'ouverture.
  function handleKeyDown(event) {
    if (open && event.key === 'Escape') {
      event.stopPropagation();
      closePanel();
    }
  }

  return (
    <>
      {home && visible && (
        <div
          className="media-subscriptions"
          onKeyDown={handleKeyDown}
        >
          <button
            ref={trigger}
            type="button"
            className="media-subscriptions-trigger"
            aria-expanded={open}
            aria-controls="media-subscriptions-panel"
            aria-label={triggerLabel(count)}
            onClick={() => setOpen((previous) => !previous)}
          >
            Notifications{count > 0 && <span className="media-subscriptions-count">{count}</span>}
          </button>
          {open && (
            <section id="media-subscriptions-panel" className="media-subscriptions-panel" aria-label="Notifications et suivis des médias">
              <div className="media-subscriptions-heading">
                <h2>Suivi des médias</h2>
                <button type="button" className="media-subscriptions-close" onClick={closePanel} aria-label="Fermer le panneau">×</button>
              </div>
              {storageError && <p className="media-subscriptions-error" role="alert">{storageError}</p>}
              <div className="media-subscriptions-section">
                <h3>Notifications</h3>
                {count === 0 ? <p className="media-subscriptions-empty">Aucune nouveauté en attente.</p> : (
                  <ul>
                    {notifications.map((notification) => (
                      <li key={notification.id} className="media-subscriptions-item">
                        <div className="media-subscriptions-item-text">
                          <strong>{notification.title}</strong>
                          <span>{notification.projectName} · {notificationLabel(notification)}</span>
                        </div>
                        <div className="media-subscriptions-actions">
                          <button type="button" onClick={() => onOpenNotification?.(notification.id)}>Ouvrir</button>
                          <button type="button" onClick={() => onDismissNotification?.(notification.id)} aria-label={`Supprimer la notification pour ${notification.title}`}>Supprimer</button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
              <div className="media-subscriptions-section">
                <div className="media-subscriptions-section-heading">
                  <h3>Abonnements</h3>
                  <button type="button" onClick={() => onCheck?.()} disabled={checking || !subscriptions.some((subscription) => subscription.enabled)}>
                    {checking ? 'Vérification…' : 'Vérifier maintenant'}
                  </button>
                </div>
                {youtubeTools && <YoutubeToolsNotice tools={youtubeTools} onUpdate={onUpdateTools} />}
                {subscriptions.length === 0 ? <p className="media-subscriptions-empty">Aucun abonnement.</p> : (
                  <ul>
                    {subscriptions.map((subscription) => (
                      <li key={subscription.id} className="media-subscriptions-item">
                        <div className="media-subscriptions-item-text">
                          <strong>{subscription.title}</strong>
                          <span>{subscription.projectName} · {sourceLabel(subscription.source)} · {subscriptionStateLabel(subscription)}</span>
                          {subscription.error && <span className="media-subscriptions-error" role="status">{presentStoredError(subscription.error)}</span>}
                        </div>
                        <div className="media-subscriptions-actions">
                          {subscription.status === 'missing' && <button type="button" onClick={() => onRelocateSubscription?.(subscription.id)}>Retrouver le projet</button>}
                          <button type="button" onClick={() => onToggleSubscription?.(subscription.id)}>{subscription.enabled ? 'Suspendre' : 'Reprendre'}</button>
                          <button type="button" onClick={() => onRemoveSubscription?.(subscription.id)} aria-label={`Supprimer le suivi de ${subscription.title}`}>Supprimer</button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </section>
          )}
        </div>
      )}
      {/* Région annoncée montée en permanence : seul son contenu change. */}
      <div className="media-subscriptions-toast-region" role="status" aria-live="polite">
        {toast && (
          <div className="media-subscriptions-toast">
            <div className="media-subscriptions-item-text">
              <strong>{toast.title}</strong>
              <span>{toast.projectName} · {notificationLabel(toast)}</span>
            </div>
            <button type="button" onClick={() => onOpenNotification?.(toast.id)}>Ouvrir</button>
            <button type="button" className="media-subscriptions-close" onClick={() => onCloseToast?.()} aria-label="Fermer la notification">×</button>
          </div>
        )}
      </div>
    </>
  );
}

export default MediaSubscriptionsPanel;

