import { useState } from 'react';
import { AppModalPortal } from '../common/AppModalPortal';
import { Button } from '../common/Button';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import { pathKey } from '../../utils/fileUtils';
import './SessionMediaTriageModal.css';

// Sous-dossier de session d'origine (voix-generees, enregistrements…) : aide à
// reconnaître une prise IA d'un import. Dernier segment de dossier du chemin.
function parentFolderHint(path) {
  const segments = String(path).replace(/\\/g, '/').split('/');
  return segments.length >= 2 ? segments[segments.length - 2] : '';
}

/**
 * Tri des médias de session non utilisés à la promotion.
 * Tout est coché par défaut ; « Conserver la sélection » copie les cochés dans
 * le workspace, « Tout abandonner » les laisse partir avec la session.
 * Escape et clic hors de la boîte valent « Conserver la sélection » (choix sûr).
 */
export function SessionMediaTriageModal({ items, onResolve }) {
  const [checkedKeys, setCheckedKeys] = useState(() => new Set(items.map((item) => pathKey(item.path))));

  function toggle(path) {
    const key = pathKey(path);
    setCheckedKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }

  function confirmKeepSelection() {
    onResolve({ keptPaths: items.filter((item) => checkedKeys.has(pathKey(item.path))).map((item) => item.path) });
  }

  useEscapeKey(true, confirmKeepSelection);

  return (
    <AppModalPortal className="session-triage-overlay">
      <div className="session-triage-backdrop" onClick={confirmKeepSelection}>
        <div className="modal-box session-triage-box" onClick={(e) => e.stopPropagation()}>
          <div className="modal-header">
            <span>Médias non utilisés</span>
          </div>
          <div className="session-triage-body">
            <p className="session-triage-intro">
              {items.length === 1
                ? '1 média de ta session n’est utilisé par aucune histoire.'
                : `${items.length} médias de ta session ne sont utilisés par aucune histoire.`}
              {' '}Coche ceux à conserver avec le projet ; les autres seront supprimés avec la session.
            </p>
            <ul className="session-triage-list">
              {items.map((item) => (
                <li key={item.path}>
                  <label className="session-triage-item">
                    <input
                      type="checkbox"
                      checked={checkedKeys.has(pathKey(item.path))}
                      onChange={() => toggle(item.path)}
                    />
                    <span className="session-triage-name" title={item.path}>{item.filename}</span>
                    {parentFolderHint(item.path) && (
                      <span className="session-triage-hint">{parentFolderHint(item.path)}</span>
                    )}
                  </label>
                </li>
              ))}
            </ul>
          </div>
          <div className="session-triage-footer">
            <Button variant="danger-outline" onClick={() => onResolve({ keptPaths: [] })}>
              Tout abandonner
            </Button>
            <Button variant="primary" onClick={confirmKeepSelection}>
              Conserver la sélection
            </Button>
          </div>
        </div>
      </div>
    </AppModalPortal>
  );
}

sources.src/components/layout/PackAudioProcessin:
import { useId, useState } from 'react';
import { Toggle } from '../common/Toggle';
import { Tooltip } from '../common/Tooltip';
import { Button } from '../common/Button';
import { Pencil } from '../icons/LucideLocal';
import {
  PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS,
  formatPackAudioEdgeSilence,
  getPackAudioEdgeSilenceSettings,
  parsePackAudioEdgeSilenceOverride,
  resolvePackAudioEdgeSilence,
} from '../../config/audioProcessing';
import './PackAudioProcessingFields.css';

const HARMONIZE_LOUDNESS_HELP = "Aligne le volume de toutes les histoires sur un même niveau (-14 LUFS) à la génération (recommandé si tes fichiers audio ne sont pas déjà préparés pour la Lunii). Une source très faible ou dynamique est quand même mise à niveau ; Story Studio signale après génération si le traitement a dû être particulièrement fort. Si désactivé : le volume d'origine de chaque fichier est conservé.";

function silenceModePresentation(leadingSeconds, trailingSeconds) {
  const leadingLabel = formatPackAudioEdgeSilence(leadingSeconds);
  const trailingLabel = formatPackAudioEdgeSilence(trailingSeconds);

  return {
    durationSummary: leadingSeconds === trailingSeconds
      ? leadingLabel
      : `${leadingLabel} / ${trailingLabel}`,
    options: [
      ['normalize', 'Ajuster', 'Mesurer et ajuster les silences de début et de fin', `Recommandé : mesure les silences et les ramène à exactement ${leadingLabel} au début et ${trailingLabel} à la fin (coupe si trop long, complète si trop court).`],
      ['add', 'Ajouter', `Ajouter ${leadingLabel} au début et ${trailingLabel} à la fin`, `Ajoute ${leadingLabel} au début et ${trailingLabel} à la fin sans mesurer l'existant — le silence déjà présent s'additionne.`],
      ['off', 'Ne rien faire', 'Ne pas modifier les silences de début et de fin', 'Ne touche pas aux silences de début et de fin.'],
    ],
  };
}

const DURATION_ERROR = `Saisis une durée de 0 à ${PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS} s, ou laisse vide.`;

function durationText(seconds) {
  return formatPackAudioEdgeSilence(seconds).replace(/\s*s$/u, '');
}

function durationInputValue(override, inherited) {
  if (override == null) return durationText(inherited);
  if (typeof override === 'number') return durationText(override);
  return String(override);
}

// Une saisie vidée n'est pas une personnalisation : elle reprend la préférence.
function isCustomized(override) {
  return override != null && String(override).trim() !== '';
}

// Appelée comme une fonction, sans hook : les deux saisies restent dans l'arbre
// rendu par la fiche.
function durationField({ id, label, override, inherited, preference, noteId, onChange }) {
  const invalid = parsePackAudioEdgeSilenceOverride(override) === undefined;
  const errorId = `${id}-error`;
  return (
    <div className="pack-meta-audio-duration-field">
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        className="pack-meta-audio-duration-input"
        type="text"
        inputMode="decimal"
        value={durationInputValue(override, inherited)}
        // Visible seulement quand le champ est vidé : la valeur reprise des
        // Préférences, celle qui partira à la génération.
        placeholder={durationText(preference)}
        aria-invalid={invalid || undefined}
        aria-describedby={invalid ? `${errorId} ${noteId}` : noteId}
        onChange={(event) => onChange(event.target.value)}
      />
      {invalid && (
        <span id={errorId} className="pack-meta-audio-duration-error">
          {DURATION_ERROR}
        </span>
      )}
    </div>
  );
}

export function PackAudioProcessingFields({ values, onChange }) {
  const preferences = getPackAudioEdgeSilenceSettings();
  const { leading, trailing } = resolvePackAudioEdgeSilence(values, preferences);
  const { durationSummary, options } = silenceModePresentation(leading, trailing);
  const activeMode = values.silenceMode;
  const activeHelp = (options.find(([mode]) => mode === activeMode) ?? options[0])[3];
  const leadingOverride = values.leadingSilenceSec;
  const trailingOverride = values.trailingSilenceSec;
  const hasOverrides = isCustomized(leadingOverride) || isCustomized(trailingOverride);
  const hasInvalidDuration = [leadingOverride, trailingOverride]
    .some((override) => parsePackAudioEdgeSilenceOverride(override) === undefined);
  const [editingDurations, setEditingDurations] = useState(false);
  // Identifiants stables par instance : le stylo pointe le groupe qu'il ouvre.
  const baseId = useId();
  const editorId = `${baseId}-durations`;
  const noteId = `${baseId}-durations-note`;

  function updateField(field, value) {
    onChange?.(field, value);
  }

  function resetDurations() {
    updateField('leadingSilenceSec', null);
    updateField('trailingSilenceSec', null);
  }

  return (
    <section className="pack-meta-audio" aria-label="Traitement audio du pack">
      <span className="pack-meta-cover-label">Traitement audio</span>

      <Tooltip text={HARMONIZE_LOUDNESS_HELP} wrap className="pack-meta-audio-volume-tooltip">
        <div className="pack-meta-audio-volume-row">
          <span className="pack-meta-audio-control-title">Harmoniser le volume</span>
          <Toggle
            on={values.harmonizeLoudness}
            onChange={(value) => updateField('harmonizeLoudness', value)}
            ariaLabel="Harmoniser le volume des audios vers -14 LUFS à la génération."
          />
        </div>
      </Tooltip>

      <div className="pack-meta-audio-silence">
        <div className="pack-meta-audio-silence-heading">
          <span className="pack-meta-audio-control-title">Silence début / fin</span>
          <span className="pack-meta-audio-duration">{durationSummary}</span>
          <span className="pack-meta-audio-duration-scope">
            {hasOverrides ? 'Personnalisé' : 'Par défaut'}
          </span>
          <Tooltip text={editingDurations ? 'Fermer les durées' : 'Modifier les durées du pack'} asChild>
            <Button
              size="sm"
              variant="icon"
              className="pack-meta-audio-duration-edit"
              aria-label={editingDurations ? 'Fermer la modification des durées' : 'Modifier les durées du pack'}
              aria-expanded={editingDurations}
              aria-controls={editorId}
              onClick={() => setEditingDurations((current) => !current)}
            >
              <Pencil />
            </Button>
          </Tooltip>
        </div>
        {hasInvalidDuration && !editingDurations && (
          <span className="pack-meta-audio-duration-invalid-hint" role="status">
            Corrige les durées personnalisées avant d’appliquer.
          </span>
        )}
        {/* Le groupe reste dans le DOM, masqué : `aria-controls` doit toujours
            désigner un élément existant. */}
        <div
          id={editorId}
          className="pack-meta-audio-duration-editor"
          role="group"
          aria-label="Durées de silence personnalisées"
          hidden={!editingDurations}
        >
          {editingDurations && (
            <>
              <div className="pack-meta-audio-duration-fields">
                {durationField({
                  id: `${baseId}-leading`,
                  label: 'Début (s)',
                  override: leadingOverride,
                  inherited: leading,
                  preference: preferences.leading,
                  noteId,
                  onChange: (value) => updateField('leadingSilenceSec', value),
                })}
                {durationField({
                  id: `${baseId}-trailing`,
                  label: 'Fin (s)',
                  override: trailingOverride,
                  inherited: trailing,
                  preference: preferences.trailing,
                  noteId,
                  onChange: (value) => updateField('trailingSilenceSec', value),
                })}
              </div>
              <span id={noteId} className="pack-meta-audio-duration-note">
                {`De 0 à ${PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS} s. Un champ vide reprend la valeur des Préférences.`}
              </span>
              <div className="pack-meta-audio-duration-actions">
                <Button
                  size="sm"
                  variant="ghost"
                  className="pack-meta-audio-duration-reset"
                  disabled={!hasOverrides}
                  onClick={resetDurations}
                >
                  Reprendre les valeurs par défaut
                </Button>
              </div>
            </>
          )}
        </div>
        <div className="pack-meta-audio-options" role="group" aria-label="Mode de silence début et fin">
          {options.map(([mode, label, ariaLabel, help]) => (
            <Tooltip key={mode} text={help} wrap className="pack-meta-audio-segment-tooltip">
              <button
                type="button"
                className={`pack-meta-age-chip pack-meta-audio-segment ${activeMode === mode ? 'is-active' : ''}`}
                aria-pressed={activeMode === mode}
                aria-label={ariaLabel}
                onClick={() => updateField('silenceMode', mode)}
              >
                <span className="pack-meta-audio-option-dot" aria-hidden="true" />
                <span>{label}</span>
              </button>
            </Tooltip>
          ))}
        </div>
        <span className="pack-meta-audio-help">{activeHelp}</span>
      </div>
    </section>
  );
}

