import { normalizeStoryEntry } from './schema.js';
import { getAssemblyReplacementEligibility, validateMediaAudioToolRequest } from '../mediaToolContext.js';

const TERMINAL_FIELDS = [
  'controlSettings',
  'returnAfterPlay',
  'returnOnHome',
  'returnOnHomeNone',
  'afterPlaybackPromptAudio',
  'afterPlaybackPromptControlSettings',
  'afterPlaybackPromptOkTarget',
  'afterPlaybackPromptHomeTarget',
  'afterPlaybackPromptHomeNone',
  'afterPlaybackSequence',
  'afterPlaybackHomeStep',
];

function failure(project, code, reason, details = {}) {
  return { ok: false, project, code, reason, ...details };
}

function terminalFieldsFrom(story) {
  return Object.fromEntries(TERMINAL_FIELDS.map((field) => [field, story?.[field]]));
}

function replaceSelectedSiblings(entries, retainedId, removedIds, replacement) {
  const next = [];
  for (const entry of entries ?? []) {
    if (entry.id === retainedId) {
      next.push(replacement);
    } else if (removedIds.has(entry.id)) {
      continue;
    } else if (entry.type === 'menu') {
      next.push({
        ...entry,
        children: replaceSelectedSiblings(entry.children ?? [], retainedId, removedIds, replacement),
      });
    } else {
      next.push(entry);
    }
  }
  return next;
}

export function replaceStoriesWithAssembledStory(project, {
  request,
  entryIds,
  outputPath,
  logicalName,
}) {
  const ids = entryIds ?? request?.entryIds ?? [];
  if (request) {
    const validation = validateMediaAudioToolRequest(project, request);
    if (!validation.valid) return failure(project, validation.code, validation.reason);
  }
  if (!outputPath) return failure(project, 'missing-output', 'Le fichier assemblé est introuvable.');
  const eligibility = getAssemblyReplacementEligibility(project, ids);
  if (!eligibility.valid) return failure(project, eligibility.code, eligibility.reason, eligibility);

  const first = eligibility.stories[0];
  const last = eligibility.stories.at(-1);
  const replacement = normalizeStoryEntry({
    ...first,
    ...terminalFieldsFrom(last),
    id: first.id,
    name: String(logicalName || '').trim() || first.name,
    audio: outputPath,
  });
  const removedIds = new Set(eligibility.entryIds.slice(1));
  return {
    ok: true,
    project: {
      ...project,
      rootEntries: replaceSelectedSiblings(project.rootEntries ?? [], first.id, removedIds, replacement),
    },
    retainedId: first.id,
    removedIds: [...removedIds],
  };
}

sources.src/hooks/useMediaSubscriptions.js:
import { useMessageLanguage } from '../i18n/useMessageLanguage.js';
import { presentStoredError, userMessageTransport } from '../i18n/userMessage.js';
import { useEffect, useRef, useState } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { exists } from '@tauri-apps/plugin-fs';
import { open } from '@tauri-apps/plugin-dialog';
import {
  loadRegistryState, persistRegistry, syncProjectSubscriptions, beginCheck, recordCheckResult,
  getNotifications, dismissNotification, removeSubscription, setSubscriptionPaused, acknowledgeEpisodes,
  markSubscriptionMissing, relocateSubscription, REGISTRY_WRITE_ERROR,
} from '../store/mediaSubscriptions.js';
import {
  fetchSubscriptionSnapshot, SUBSCRIPTIONS_SAVED_EVENT, sameSubscriptionSource,
  setProjectSubscriptionLookup, youtubeSubscriptionKind, TOOL_MISSING_CODE, normalizeToolStatus,
} from '../store/mediaSubscriptionSource.js';
import { KEYS, read } from '../store/persistentSettings.js';
import { pathKey } from '../utils/fileUtils.js';
import { generateUuid } from '../utils/uuid.js';
import { loadProjectFromPath } from '../store/projectIO.js';
import { isTauriRuntime } from '../utils/tauriRuntime.js';
import { logger } from '../utils/logger.js';

const MISSING_PROJECT_ERROR = 'Projet introuvable. Utilise « Retrouver le projet ».';
// yt-dlp n'est préparé (téléchargé, mis à jour) qu'après l'accord donné dans
// l'import YouTube : une vérification de fond ne le déclenche jamais d'elle-même.
const YOUTUBE_NOT_READY_ERROR = 'Vérification reportée : ouvre une fois l’import YouTube sur cette machine pour préparer yt-dlp.';

const NO_TOOL_UPDATE = { running: false, error: null };

function toolStatusNeedsAction(status) {
  return !!status && (status.ytdlpMissing || status.ytdlpUpdateDue || status.jsRuntimeMissing);
}

function samePath(left, right) {
  return !!left && !!right && pathKey(left) === pathKey(right);
}

// Le registre ne contient que les suivis explicitement activés sur cette machine.
// Les écritures projet sont observées après succès ; aucune vérification ne
// modifie un .mbah ni les médias de l'utilisateur.
export function useMediaSubscriptions({ store, openProject, onShowImport, showErrorDialog }) {
  useMessageLanguage();
  const [initial] = useState(loadRegistryState);
  const [registry, setRegistry] = useState(initial.registry);
  const [storageError, setStorageError] = useState(initial.error);
  const [checking, setChecking] = useState(false);
  const [toasts, setToasts] = useState([]);
  // État des outils YouTube constaté par la dernière vérification de fond. Il
  // n'est pas persisté : chaque lancement le constate à nouveau, sans
  // jamais télécharger, et le panneau propose la mise à jour.
  const [toolStatus, setToolStatus] = useState(null);
  const [toolUpdate, setToolUpdate] = useState(NO_TOOL_UPDATE);
  const updatingTools = useRef(false);
  const toast = toasts[0] ?? null;
  const registryRef = useRef(registry);
  // Registre illisible qu'aucune copie n'a pu protéger : il n'est pas écrasé.
  const readOnly = useRef(initial.readOnly === true);
  const live = useRef({ store, openProject, onShowImport, showErrorDialog });
  live.current = { store, openProject, onShowImport, showErrorDialog };
  const authorized = useRef(new Set());
  const running = useRef(false);
  const checkAgain = useRef(false);
  const opening = useRef(false);
  const mounted = useRef(false);

  function update(transform) {
    const next = transform(registryRef.current);
    registryRef.current = next;
    const saved = !readOnly.current && persistRegistry(next);
    if (!saved && !readOnly.current) logger.warn('media-subscriptions:registry-write-failed');
    if (mounted.current) {
      setStorageError((current) => (saved
        ? (current === REGISTRY_WRITE_ERROR ? null : current)
        : (current || REGISTRY_WRITE_ERROR)));
      setRegistry(next);
      const notifications = getNotifications(next);
      setToasts((queue) => queue.flatMap((item) => {
        const notification = notifications.find((entry) => entry.id === item.id);
        return notification ? [notification] : [];
      }));
    }
    return next;
  }

  async function check() {
    if (!isTauriRuntime()) return;
    if (running.current) { checkAgain.current = true; return; }
    running.current = true;
    setChecking(true);
    try {
      for (const item of [...registryRef.current.subscriptions]) {
        if (!mounted.current) break;
        if (item.paused) continue;
        const started = beginCheck(registryRef.current, item.id);
        update(() => started.registry);
        const isCurrent = () => mounted.current && registryRef.current.subscriptions.some((entry) => entry.id === item.id && entry.revision === started.revision && !entry.paused);
        try {
          if (!(await exists(item.projectPath))) {
            if (!isCurrent()) continue;
            update((current) => recordCheckResult(current, item.id, started.revision, { error: MISSING_PROJECT_ERROR, status: 'missing' }));
            continue;
          }
          if (item.source === 'youtube' && read(KEYS.YOUTUBE_CGU_ACCEPTED) !== 'true') {
            if (isCurrent()) update((current) => recordCheckResult(current, item.id, started.revision, { error: YOUTUBE_NOT_READY_ERROR }));
            continue;
          }
          // Jamais de téléchargement d'outil en arrière-plan : la mise à jour
          // est proposée dans le panneau et reste une action explicite.
          const snapshot = await fetchSubscriptionSnapshot(item, invoke, {
            ytdlpPath: read(KEYS.YTDLP_CUSTOM_PATH) || null, isCurrent,
            knownIds: new Set([...item.baselineIds, ...item.seenIds, ...item.pendingIds]),
            installedToolsOnly: item.source === 'youtube',
          });
          if (snapshot.tools && mounted.current) setToolStatus(snapshot.tools);
          if (!isCurrent()) continue;
          const before = getNotifications(registryRef.current).find((notification) => notification.subscriptionId === item.id)?.count ?? 0;
          const next = update((current) => recordCheckResult(current, item.id, started.revision, snapshot));
          const notification = getNotifications(next).find((entry) => entry.subscriptionId === item.id);
          if (notification && notification.count > before) setToasts((queue) => [
            ...queue.filter((entry) => entry.id !== notification.id), notification,
          ]);
        } catch (error) {
          if (error?.code === TOOL_MISSING_CODE && mounted.current) setToolStatus(normalizeToolStatus({ ytdlpMissing: true }));
          if (isCurrent()) update((current) => recordCheckResult(current, item.id, started.revision, { error: userMessageTransport(error) }));
        }
      }
    } finally {
      running.current = false;
      if (mounted.current) setChecking(false);
      if (mounted.current && checkAgain.current) {
        checkAgain.current = false;
        void check();
      }
    }
  }

  // Abonnement du registre rattaché au projet ouvert lui-même, pas à une copie
  // de son fichier enregistrée ailleurs.
  function registeredHere(id) {
    const entry = registryRef.current.subscriptions.find((item) => item.id === id);
    return entry && samePath(entry.projectPath, live.current.store.savePath) ? entry : null;
  }

  function findConfig(request) {
    const configs = live.current.store.project?.mediaSubscriptions ?? [];
    return (request.subscriptionId && configs.find((item) => item.id === request.subscriptionId && item.source === request.source))
      || configs.find((item) => sameSubscriptionSource(item, request))
      || null;
  }

  useEffect(() => {
    mounted.current = true;
    function saved(event) {
      const { projectPath, previousProjectPath, projectName, configs } = event.detail;
      const known = new Set(registryRef.current.subscriptions.filter((item) => pathKey(item.projectPath) === pathKey(projectPath)
        || (previousProjectPath && pathKey(item.projectPath) === pathKey(previousProjectPath))).map((item) => item.id));
      update((current) => {
        const allowed = configs.filter((item) => known.has(item.id) || authorized.current.has(item.id))
          .map((config) => {
            const existing = current.subscriptions.find((item) => item.id === config.id);
            // A local pause/resume is authoritative until another explicit
            // checkbox action, even when the saved project carries an older flag.
            return existing && !authorized.current.has(config.id)
              ? { ...config, enabled: !existing.paused } : config;
          });
        let next = syncProjectSubscriptions(current, projectPath, projectName, allowed);
        for (const config of allowed) {
          if (authorized.current.has(config.id)) next = setSubscriptionPaused(next, config.id, config.enabled === false);
        }
        return next;
      });
      for (const item of configs) authorized.current.delete(item.id);
    }
    window.addEventListener(SUBSCRIPTIONS_SAVED_EVENT, saved);
    const releaseLookup = setProjectSubscriptionLookup((source, url) => {
      const config = findConfig({ source, url });
      if (!config) return null;
      const entry = registeredHere(config.id);
      const state = entry
        ? (entry.paused ? 'paused' : 'active')
        : (authorized.current.has(config.id) && config.enabled ? 'pending' : 'inactive');
      return { subscriptionId: config.id, state };
    });
    // Deferred so the StrictMode probe cannot launch a second network batch.
    const timer = setTimeout(() => { void check(); }, 0);
    return () => {
      mounted.current = false;
      clearTimeout(timer);
      releaseLookup();
      window.removeEventListener(SUBSCRIPTIONS_SAVED_EVENT, saved);
    };
    // Runtime refs keep callbacks current without checking on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function prepareRequest(request) {
    if (!request?.enabled) return request;
    const epoch = live.current.store.workEpochRef.current;
    if (request.baselineComplete !== false) return request;
    // Sans changement explicite de la case, ou pour un suivi déjà au registre
    // de ce projet, la référence connue reste celle du suivi : aucune relecture.
    const existing = findConfig(request);
    if (existing && (request.enabledTouched !== true || registeredHere(existing.id))) return request;
    const snapshot = await fetchSubscriptionSnapshot(request, invoke, { ytdlpPath: read(KEYS.YTDLP_CUSTOM_PATH) || null });
    if (epoch !== live.current.store.workEpochRef.current) throw new Error('Le projet a changé pendant la préparation du suivi.');
    return { ...request, baselineIds: snapshot.episodeIds, baselineComplete: true };
  }

  function replaceConfig(currentStore, previousId, config) {
    currentStore.setProject((project) => ({ ...project, mediaSubscriptions: [
      ...(project.mediaSubscriptions ?? []).filter((item) => item.id !== previousId && item.id !== config.id), config,
    ] }));
  }

  function applyRequest(request, importedEpisodeIds = []) {
    if (!request) return;
    const currentStore = live.current.store;
    const followable = request.source !== 'youtube' || !!youtubeSubscriptionKind(request.url);
    const existing = findConfig(request);
    if (!existing) {
      if (!request.enabled || !followable) return;
      const id = generateUuid();
      authorized.current.add(id);
      replaceConfig(currentStore, id, {
        id, source: request.source, url: request.url, title: request.title, baselineIds: request.baselineIds, enabled: true,
      });
      return;
    }
    if (registeredHere(existing.id)) update((current) => acknowledgeEpisodes(current, existing.id, importedEpisodeIds));
    // Seul un changement explicite de la case modifie le suivi : un import
    // fait sans y toucher ne peut ni l'activer ni le suspendre.
    if (request.enabledTouched !== true) return;
    const entry = registryRef.current.subscriptions.find((item) => item.id === existing.id);
    if (entry && !samePath(entry.projectPath, currentStore.savePath)) {
      // Copie de fichier d'un projet suivi : l'identifiant appartient à
      // l'original. La copie reçoit le sien plutôt que de lui prendre son suivi.
      if (!request.enabled) {
        replaceConfig(currentStore, existing.id, { ...existing, enabled: false });
        return;
      }
      const id = generateUuid();
      authorized.current.add(id);
      replaceConfig(currentStore, existing.id, { ...existing, id, baselineIds: request.baselineIds, enabled: true });
      return;
    }
    authorized.current.add(existing.id);
    replaceConfig(currentStore, existing.id, {
      ...existing, enabled: !!request.enabled, ...(!entry ? { baselineIds: request.baselineIds } : {}),
    });
  }

  async function openNotification(id) {
    if (opening.current) return;
    const item = registryRef.current.subscriptions.find((entry) => entry.id === id);
    if (!item) return;
    opening.current = true;
    try {
      const currentStore = live.current.store;
      if (pathKey(currentStore.savePath ?? '') !== pathKey(item.projectPath)) {
        if (!(await exists(item.projectPath))) {
          update((current) => markSubscriptionMissing(current, id, MISSING_PROJECT_ERROR));
          setToasts((queue) => queue.filter((entry) => entry.id !== id));
          live.current.showErrorDialog({
            title: 'Ouvrir le projet suivi',
            message: `Le projet « ${item.projectName || item.projectPath} » est introuvable. Utilise « Retrouver le projet » dans le panneau Notifications pour le désigner à nouveau.`,
            variant: 'warning',
          });
          return;
        }
        const opened = await live.current.openProject(item.projectPath);
        if (!opened) return;
      }
      const current = registryRef.current.subscriptions.find((entry) => entry.id === id);
      if (!mounted.current || !current || current.projectPath !== item.projectPath) return;
      setToasts((queue) => queue.filter((entry) => entry.id !== id));
      live.current.onShowImport({ ...current, enabled: !current.paused, subscriptionId: current.id });
    } catch (error) {
      live.current.showErrorDialog({ title: 'Ouvrir le projet suivi', message: error });
    } finally {
      opening.current = false;
    }
  }

  async function relocate(id) {
    const path = await open({ multiple: false, filters: [{ name: 'Projet Story Studio', extensions: ['mbah'] }] });
    if (!path) return;
    try {
      const { data: project } = await loadProjectFromPath(path);
      if (!project.mediaSubscriptions?.some((item) => item.id === id)) throw new Error('Ce projet ne contient pas cet abonnement.');
      // Un suivi mis en pause par l'utilisateur reste en pause une fois retrouvé.
      update((current) => relocateSubscription(current, id, path, project.projectName));
    } catch (error) {
      live.current.showErrorDialog({ title: 'Retrouver le projet', message: error });
    }
  }

  // Installation ou mise à jour explicite, par la commande des préférences
  // (yt-dlp et moteur JavaScript), puis nouvelle vérification.
  async function updateTools() {
    if (updatingTools.current) return;
    updatingTools.current = true;
    setToolUpdate({ running: true, error: null });
    try {
      await invoke('update_ytdlp');
      if (!mounted.current) return;
      setToolStatus(null);
      setToolUpdate(NO_TOOL_UPDATE);
      void check();
    } catch (error) {
      if (mounted.current) setToolUpdate({ running: false, error: { userMessage: error, prefix: "Mise à jour impossible : " } });
    } finally {
      updatingTools.current = false;
    }
  }

  const followsYoutube = registry.subscriptions.some((item) => item.source === 'youtube');
  const youtubeTools = followsYoutube && toolStatusNeedsAction(toolStatus)
    ? { missing: toolStatus.ytdlpMissing, updating: toolUpdate.running, error: toolUpdate.error == null ? null : presentStoredError(toolUpdate.error) }
    : null;

  return {
    prepareRequest, applyRequest,
    panelProps: {
      subscriptions: registry.subscriptions.map((item) => ({ ...item, enabled: !item.paused })),
      notifications: getNotifications(registry), checking, toast, storageError,
      youtubeTools, onUpdateTools: updateTools,
      onCheck: check, onOpenNotification: openNotification,
      onCloseToast: () => setToasts((queue) => queue.slice(1)),
      onDismissNotification: (id) => update((current) => dismissNotification(current, id)),
      onToggleSubscription: (id) => {
        const item = registryRef.current.subscriptions.find((entry) => entry.id === id);
        if (!item) return;
        const paused = !item.paused;
        update((current) => setSubscriptionPaused(current, id, paused));
        if (!paused) void check();
      },
      onRemoveSubscription: (id) => { authorized.current.delete(id); update((current) => removeSubscription(current, id)); },
      onRelocateSubscription: relocate,
    },
  };
}

sources.src/hooks/useMediaToolBridge.js:
import { useCallback, useRef, useState } from 'react';
import {
  buildMediaAudioToolRequest,
  haveSameMediaPathMultiset,
  validateMediaAudioToolRequest,
} from '../store/mediaToolContext.js';

let requestSequence = 0;

function nextRequestId() {
  requestSequence += 1;
  return `media-tool-${Date.now()}-${requestSequence}`;
}

function invalidResult(code, reason) {
  return { ok: false, code, reason };
}

export function useMediaToolBridge({
  project,
  statusByPath,
  openMediaTab,
  mutations,
  showErrorDialog,
}) {
  const [activeRequest, setActiveRequest] = useState(null);
  const activeRequestRef = useRef(null);
  const projectRef = useRef(project);
  const statusByPathRef = useRef(statusByPath);
  const projectRevisionRef = useRef(0);
  const previousProjectRef = useRef(project);

  if (previousProjectRef.current !== project) {
    previousProjectRef.current = project;
    projectRevisionRef.current += 1;
  }
  projectRef.current = project;
  statusByPathRef.current = statusByPath;
  activeRequestRef.current = activeRequest;

  const openMediaAudioTool = useCallback((spec) => {
    const built = buildMediaAudioToolRequest({
      project: projectRef.current,
      statusByPath: statusByPathRef.current,
      entryIds: spec?.entryIds,
      origin: spec?.origin,
      tool: spec?.tool,
      requestId: nextRequestId(),
    });
    if (!built.valid) {
      showErrorDialog?.({
        title: 'Outil audio indisponible',
        message: built.reason,
        variant: 'warning',
      });
      return built;
    }
    const request = {
      ...built.request,
      status: 'pending',
      projectRevision: projectRevisionRef.current,
    };
    activeRequestRef.current = request;
    setActiveRequest(request);
    openMediaTab?.();
    return { valid: true, request };
  }, [openMediaTab, showErrorDialog]);

  const acknowledgeRequest = useCallback((requestId) => {
    setActiveRequest((current) => {
      if (!current || current.requestId !== requestId || current.status !== 'pending') return current;
      const next = { ...current, status: 'active' };
      activeRequestRef.current = next;
      return next;
    });
  }, []);

  const invalidateRequest = useCallback((requestId = null) => {
    setActiveRequest((current) => {
      if (requestId && current?.requestId !== requestId) return current;
      activeRequestRef.current = null;
      return null;
    });
  }, []);

  const validateRequest = useCallback((request) => {
    if (!request || activeRequestRef.current?.requestId !== request.requestId) {
      return { valid: false, code: 'inactive-request', reason: 'Cette opération contextuelle n’est plus active.' };
    }
    if (request.projectRevision !== projectRevisionRef.current) {
      return { valid: false, code: 'project-changed', reason: 'Le projet a changé pendant le traitement.' };
    }
    return validateMediaAudioToolRequest(projectRef.current, request, statusByPathRef.current);
  }, []);

  const applyProjectAction = useCallback(({ request, action, result }) => {
    const validation = validateRequest(request);
    if (!validation.valid) return invalidResult(validation.code, validation.reason);

    let outcome;
    if (action === 'replace-stories-with-assembly') {
      if (
        request.tool !== 'assemble'
        || !haveSameMediaPathMultiset(result?.inputPaths, request.sourcePaths)
      ) {
        return invalidResult('action-not-allowed', 'Les fichiers assemblés ne correspondent plus aux histoires sélectionnées.');
      }
      outcome = mutations.handleReplaceStoriesWithAssembledStory({
        request,
        outputPath: result?.createdPaths?.[0],
        logicalName: result?.logicalName,
      });
    } else {
      return invalidResult('unknown-action', 'Cette action projet n’est pas reconnue.');
    }

    if (!outcome?.ok) return invalidResult(outcome?.code ?? 'mutation-refused', outcome?.reason ?? 'La modification du projet a été refusée.');
    invalidateRequest(request.requestId);
    return outcome;
  }, [invalidateRequest, mutations, validateRequest]);

  return {
    activeRequest,
    openMediaAudioTool,
    acknowledgeRequest,
    invalidateRequest,
    validateRequest,
    applyProjectAction,
  };
}

sources.src/hooks/useMediaTransferHandlers.js:
import { presentUserMessage } from '../i18n/userMessage.js';
import { beginProjectMediaOutput } from '../store/projectMediaOutput';
import { useCallback } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { ask } from '@tauri-apps/plugin-dialog';
import {
  collectTransferableProjectFiles,
  copyMediaToWorkspace,
  getWorkspaceDir,
  isAlreadyManagedFile,
  transferProjectFilesToProject,
} from '../store/projectIO';
import { findEntryById } from '../store/projectModel';
import { pathKey } from '../utils/fileUtils';
import { FICHIERS_IMPORTES } from '../store/workspaceDirs';
import { buildTransferPromptSignature } from '../store/projectHelpers';

import { formatFrenchCount } from '../utils/frenchText.js';
import { logger } from '../utils/logger';

export function useMediaTransferHandlers({
  store,
  mediaStorageRef = null,
  sessionModeRef = null,
  copyImportedFilesEnabled,
  setCopyImportedFilesEnabled,
  workspaceDir,
  setWorkspaceDirState,
  workspaceDirRef,
  savePathRef,
  pathAudit,
  dismissedTransferPromptRef,
  setSaveToast,
  persistProjectSnapshotRef,
  showErrorDialog,
  addPathsToMediaLibrary,
}) {
  // `artifactCopies` reçoit les copies annexes — la source d'une image éditée —
  // pour qu'un appelant dont le geste échoue puisse tout retirer
  // (`discardMediaCopies`). La copie principale est le chemin rendu.
  const maybeCopyToProject = useCallback(async (filePath, { artifactCopies = null, mediaStorage = null, mediaOutput = null } = {}) => {
    if (!copyImportedFilesEnabled) return filePath;
    const captured = mediaStorage ?? { ...(mediaStorageRef?.current ?? {}), root: workspaceDirRef.current, storage: (store.readProject?.() ?? store.project).storage, ephemeral: sessionModeRef?.current === 'ephemeral' };
    const ws = captured.root;
    if (isAlreadyManagedFile(filePath, ws, savePathRef.current)) return filePath;
    try {
      const targetWorkspace = ws || await getWorkspaceDir();
      if (!workspaceDir) setWorkspaceDirState(targetWorkspace);
      return await copyMediaToWorkspace(
        filePath,
        targetWorkspace,
        FICHIERS_IMPORTES,
        { ...captured, root: targetWorkspace },
        { artifactCopies, mediaOutput },
      );
    } catch (e) {
      logger.error('media-transfer:copy-to-project-error', e);
      setSaveToast?.('error');
      setTimeout(() => setSaveToast?.(null), 3000);
      return filePath;
    }
  }, [mediaStorageRef, sessionModeRef, copyImportedFilesEnabled, savePathRef, setSaveToast, setWorkspaceDirState, store, workspaceDir, workspaceDirRef]);

  const copyGeneratedMediaToProject = useCallback(async (filePath, { mediaStorage = null, mediaOutput = null } = {}) => {
    const captured = mediaStorage ?? { ...(mediaStorageRef?.current ?? {}), root: workspaceDirRef.current, storage: (store.readProject?.() ?? store.project).storage, ephemeral: sessionModeRef?.current === 'ephemeral' };
    const ws = captured.root;
    if (isAlreadyManagedFile(filePath, ws, savePathRef.current)) return filePath;
    try {
      const targetWorkspace = ws || await getWorkspaceDir();
      if (!workspaceDir) setWorkspaceDirState(targetWorkspace);
      return await copyMediaToWorkspace(filePath, targetWorkspace, FICHIERS_IMPORTES, { ...captured, root: targetWorkspace }, { mediaOutput });
    } catch (e) {
      logger.error('media-transfer:copy-generated-to-project-error', e);
      setSaveToast?.('error');
      setTimeout(() => setSaveToast?.(null), 3000);
      return filePath;
    }
  }, [mediaStorageRef, sessionModeRef, savePathRef, setSaveToast, setWorkspaceDirState, store, workspaceDir, workspaceDirRef]);

  const dropOnNode = useCallback(async ({ nodeId, nodeType, path, paths, kind, clipboardMode }) => {
    if (kind !== 'audio' && kind !== 'image') return;
    const sourcePaths = (Array.isArray(paths) && paths.length > 0 ? paths : [path]).filter(Boolean);
    if (sourcePaths.length === 0) return;
    const epoch = store.workEpochRef?.current;
    const mediaStorage = { ...(mediaStorageRef?.current ?? {}), root: workspaceDirRef.current, storage: (store.readProject?.() ?? store.project).storage, ephemeral: sessionModeRef?.current === 'ephemeral' };
    const mediaOutput = mediaStorage.root ? beginProjectMediaOutput(mediaStorage) : null;
    try {
      logger.info('media-transfer:drop', {
        nodeId,
        nodeType,
        kind,
        count: sourcePaths.length,
        clipboardMode: clipboardMode || 'copy',
      });
      const finalPaths = [];
      for (const sourcePath of sourcePaths) {
        finalPaths.push(await maybeCopyToProject(sourcePath, { mediaStorage, mediaOutput }));
      }
      if (epoch != null && store.workEpochRef.current !== epoch) return;
      if (clipboardMode === 'cut') {
        for (const sourcePath of sourcePaths) {
          store.removeMediaReferences(sourcePath);
        }
      }
      if (kind === 'image') {
        const finalPath = finalPaths[0];
        if (nodeType === 'root') {
          store.updateRootMedia('rootImage', finalPath);
        } else if (nodeType === 'menu') {
          store.updateMenu(nodeId, { image: finalPath });
        } else if (nodeType === 'story') {
          store.updateItem(nodeId, { itemImage: finalPath });
        }
        return;
      }
      if (nodeType === 'root') {
        for (const finalPath of finalPaths) {
          store.addStory(null, finalPath);
        }
      } else if (nodeType === 'menu') {
        for (const finalPath of finalPaths) {
          store.addStory(nodeId, finalPath);
        }
      } else if (nodeType === 'story') {
        // Remplacement de l'audio principal : on garde l'ancien fichier visible
        // dans le gestionnaire de médias (« Non utilisés ») au lieu de le rendre
        // orphelin invisible sur le disque.
        const previousAudio = findEntryById(store.project, nodeId)?.audio;
        store.updateItem(nodeId, { audio: finalPaths[0] });
        if (previousAudio && pathKey(previousAudio) !== pathKey(finalPaths[0])) {
          addPathsToMediaLibrary?.([previousAudio]);
        }
      }
    } finally { mediaOutput?.release(); }
  }, [addPathsToMediaLibrary, maybeCopyToProject, mediaStorageRef, sessionModeRef, store, workspaceDirRef]);

  const notifyCutPaste = useCallback(({ path, kind } = {}) => {
    if (!path) return;
    logger.info('media-transfer:cut-paste', { path, kind });
    store.removeMediaReferences(path);
  }, [store]);

  const extractAudioEmbeddedImage = useCallback(async (audioPath) => {
    if (!audioPath) return null;
    try {
      return await invoke('extract_audio_embedded_image', { audioPath });
    } catch (e) {
      logger.warn('media-transfer:extract-embedded-image-error', audioPath, e);
      return null;
    }
  }, []);

  const maybeOfferTransferIntoProject = useCallback(async (project, savePath, options = {}) => {
    const {
      forcePrompt = false,
      copyEnabled = copyImportedFilesEnabled,
      skipPrompt = false,
      targetWorkspaceDir = null,
      sourceSessionDir = null,
      mediaStorage = null,
      // Enregistrement automatique : aucune question ne s'ouvre. Un transfert
      // qui aurait été proposé est seulement signalé (`deferred`) — copier
      // sans l'accord de l'auteur n'est pas permis, et l'appelant doit alors
      // laisser le projet « modifié » jusqu'au prochain enregistrement manuel.
      silent = false,
    } = options;
    if (!copyEnabled || !savePath) return { project, changed: false, copies: [] };

    const candidates = collectTransferableProjectFiles(project, savePath, pathAudit);
    if (candidates.length === 0) {
      dismissedTransferPromptRef.current = null;
      return { project, changed: false, copies: [] };
    }

    const signature = buildTransferPromptSignature(savePath, candidates);
    if (!forcePrompt && dismissedTransferPromptRef.current === signature) {
      return { project, changed: false, copies: [] };
    }
    if (silent) return { project, changed: false, copies: [], deferred: true };

    const sample = candidates.slice(0, 5).map((candidate) => `• ${candidate.filename}`).join('\n');
    const suffix = candidates.length > 5
      ? `\n• …et ${formatFrenchCount(candidates.length - 5, 'autre', 'autres')}`
      : '';
    const confirmed = skipPrompt || (await ask(
        `${formatFrenchCount(
          candidates.length,
          'fichier déjà lié au projet est',
          'fichiers déjà liés au projet sont',
        )} encore hors de l’emplacement de travail.\n\n${sample}${suffix}\n\nLes copier dans fichiers-importes/ et mettre à jour le projet ?`,
        {
          title: 'Transférer les fichiers existants ?',
          kind: 'warning',
          okLabel: 'Transférer',
          cancelLabel: 'Plus tard',
        }
      ));

    if (!confirmed) {
      dismissedTransferPromptRef.current = signature;
      return { project, changed: false, copies: [] };
    }

    const artifactCopies = [];
    const knownCopies = new Map();
    // Un Save As transmet déjà le projet et le chemin nouvellement nommés. Ne pas
    // relire le store précédent ici : pendant une promotion de session, il peut
    // encore porter le nom technique du snapshot de récupération.
    const projectPrefix = { ...(mediaStorage ?? { root: targetWorkspaceDir || workspaceDir, storage: project.storage, ephemeral: false }), sessionRoot: sourceSessionDir };
    const transferResult = await transferProjectFilesToProject(
      project,
      savePath,
      async (sourcePath) => {
        const targetWorkspace = targetWorkspaceDir || workspaceDir || await getWorkspaceDir();
        if (!targetWorkspaceDir && !workspaceDir) setWorkspaceDirState(targetWorkspace);
        return copyMediaToWorkspace(
          sourcePath,
          targetWorkspace,
          FICHIERS_IMPORTES,
          projectPrefix,
          { artifactCopies, knownCopies },
        );
      },
      pathAudit,
    );

    dismissedTransferPromptRef.current = null;

    if (transferResult.errors.length > 0) {
      const errors = transferResult.errors.slice(0, 5);
      showErrorDialog({
        title: 'Transfert incomplet',
        message: { parts: ["Certains fichiers n'ont pas pu être transférés :\n\n", ...errors.flatMap((error, index) => [
          index ? '\n• ' : '• ',
          { get parts() { return [error.label]; } },
          '\n  ', { userMessage: error.userMessage },
        ])] },
        technicalDetail: errors.map((error) => presentUserMessage(error.userMessage).technicalDetail).filter(Boolean).join('\n'),
      });
    }

    return {
      project: transferResult.project,
      changed: transferResult.copiedCount > 0,
      copies: [...transferResult.copies, ...artifactCopies],
      errors: transferResult.errors,
    };
  }, [
    copyImportedFilesEnabled,
    dismissedTransferPromptRef,
    pathAudit,
    setWorkspaceDirState,
    showErrorDialog,
    workspaceDir,
  ]);

  const handleCopyImportedFilesChange = useCallback(async (enabled) => {
    setCopyImportedFilesEnabled(enabled);
    if (!enabled || !store.savePath) return;

    try {
      const transferResult = await maybeOfferTransferIntoProject(store.project, store.savePath, {
        forcePrompt: true,
        copyEnabled: enabled,
      });
      if (transferResult.changed) {
        await persistProjectSnapshotRef.current?.(transferResult.project, store.savePath);
      }
    } catch (e) {
      logger.error('media-transfer:copy-imported-files-error', e);
      setSaveToast('error');
      setTimeout(() => setSaveToast(null), 3000);
    }
  }, [
    maybeOfferTransferIntoProject,
    persistProjectSnapshotRef,
    setCopyImportedFilesEnabled,
    setSaveToast,
    store,
  ]);

  return {
    maybeCopyToProject,
    copyGeneratedMediaToProject,
    dropOnNode,
    notifyCutPaste,
    extractAudioEmbeddedImage,
    maybeOfferTransferIntoProject,
    handleCopyImportedFilesChange,
  };
}

