import i18next from 'i18next';
import { useMessageLanguage } from '../i18n/useMessageLanguage.js';
import { useState, useEffect, useMemo, useCallback } from 'react';
import {
  buildRelinkSignature,
  collectMissingMedia,
  planAdvancedRelink,
  relinkMediaLibraryPaths,
  relinkMediaTags,
  relinkProjectMedia,
} from '../store/missingMediaRelink';
import { GESTURE_APPLIED } from '../store/advancedAuthoring/authoringSession';
import { advancedGestures } from '../store/projectModel/advancedGestures';
import { readMediaBindings } from '../store/projectModel/mediaBindings';
import { createMediaTagLookup, withMediaTag } from '../store/mediaTags';
import { isAdvancedProject } from '../store/projectWorkState';
import { pathKey } from '../utils/fileUtils';
import { logger } from '../utils/logger';

// Grappe « média manquant » extraite d'AppContent. Détecte les médias introuvables
// (dérivés mémoïsés du projet + audit disque),
// calcule une signature de déduplication et applique le relink (projet + tags +
// chemins de bibliothèque), avec sauvegarde optionnelle.
//
// La signature `dismissed*` évite de re-proposer le même relink après un rejet :
// on masque le prompt tant que la liste de manquants (donc la signature) est
// identique à celle rejetée, et on la ré-arme dès qu'elle change. Le reset sur
// changement de `store.savePath` accompagne le changement de projet courant.
//
// Fournisseurs en amont : handleSaveProject (useSaveProgress) pour `saveAfter` —
// ce hook doit donc être appelé APRÈS useSaveProgress ; pathAudit vient de
// useProjectFileAudit ; mediaLibraryPathsRef/setMediaLibraryPaths de
// useMediaLibraryPaths.
//
// HORS de ce hook (restent dans App.jsx) : le calcul de `showMissingMediaRelink`
// (mêle projectType/savePath/pathAuditPending, propres à l'hôte) et le rendu de
// MissingMediaRelinkModal.
// Côté graphe, relier un fichier déplacé est un **geste d'auteur** : il part par
// `repoint-media`, il entre dans l'historique, et il est annulable. Rien n'est
// réécrit dans le document par JavaScript, qui ne l'ouvre pas.
//
// Les gestes partent **un par un et dans l'ordre** : la session n'en accepte
// qu'un en vol et refuserait les suivants par `busy`. Un pas refusé arrête la
// série — les pas déjà appliqués restent, chacun avec son pas d'annulation, et
// l'auteur voit le refus par la notice de l'espace graphe.
//
// Conséquence assumée, faute de geste groupé dans le dialecte : **relier N
// fichiers produit N pas d'annulation**, pas un seul.
async function applyAdvancedRelink(project, replacements, advancedAuthoring) {
  const plan = planAdvancedRelink(project, replacements);
  const appliedReplacements = new Map();
  if (plan.length === 0) return { applied: 0, replacements: appliedReplacements, project: null, refusal: null };
  let latest = null;
  let applied = 0;
  for (const step of plan) {
    // `present: true` : le modal ne propose que des fichiers qu'il a vus sur le
    // disque, et c'est cette présence qui rend la liaison `resolved` plutôt que
    // `missing`.
    const gesture = advancedGestures.repointMedia(step.assetRef, { path: step.path, present: true });
    const outcome = await advancedAuthoring.runGesture(gesture);
    if (outcome?.status !== GESTURE_APPLIED) {
      logger.warn(`relink:advanced-stopped assetRef=${step.assetRef} status=${outcome?.status ?? 'inconnu'}`);
      return { applied, replacements: appliedReplacements, project: latest, refusal: outcome ?? null };
    }
    latest = outcome.project;
    applied += 1;
    appliedReplacements.set(step.previousPath, step.path);
  }
  return { applied, replacements: appliedReplacements, project: latest, refusal: null };
}

export function useMissingMediaRelink({
  store,
  advancedAuthoring,
  mediaLibraryPathsRef,
  setMediaLibraryPaths,
  pathAudit,
  handleSaveProject,
}) {
  useMessageLanguage();
  const language = i18next.resolvedLanguage ?? 'fr';
  const [dismissedMissingMediaSignature, setDismissedMissingMediaSignature] = useState('');

  useEffect(() => {
    setDismissedMissingMediaSignature('');
  }, [store.savePath]);

  const missingMedia = useMemo(
    () => collectMissingMedia(store.project, pathAudit),
    [store.project, pathAudit, language],
  );
  const missingMediaSignature = useMemo(
    () => buildRelinkSignature(missingMedia),
    [missingMedia],
  );

  const handleApplyMissingMediaRelinks = useCallback(async (replacements, { saveAfter = false } = {}) => {
    const advanced = isAdvancedProject(store.project);
    let nextProject;
    let appliedReplacements = replacements;
    let partiallyApplied = false;
    if (advanced) {
      const outcome = await applyAdvancedRelink(store.project, replacements, advancedAuthoring);
      // Les gestes ont déjà installé le projet par la session. Un refus au
      // premier pas ne laisse rien : on n'écrit alors ni étiquettes, ni
      // catalogue, ni signature, pour que la proposition se represente.
      if (outcome.applied === 0) return;
      nextProject = outcome.project;
      appliedReplacements = outcome.replacements;
      partiallyApplied = outcome.refusal !== null;
    } else {
      nextProject = relinkProjectMedia(store.project, replacements);
      store.setProject(nextProject);
    }

    // Étiquettes et catalogue suivent uniquement les fichiers effectivement
    // reliés. Une liaison refusée peut encore utiliser le même ancien fichier.
    let nextMediaTags = relinkMediaTags(store.mediaTags, appliedReplacements);
    const nextMediaLibraryPaths = relinkMediaLibraryPaths(mediaLibraryPathsRef.current, appliedReplacements);
    if (advanced && partiallyApplied) {
      const remainingBindings = readMediaBindings(nextProject);
      const remainingPaths = new Set(remainingBindings.map((binding) => pathKey(binding.path)));
      const originalTagsFor = createMediaTagLookup(store.mediaTags);
      for (const { path } of remainingBindings) {
        for (const tag of originalTagsFor(path)) nextMediaTags = withMediaTag(nextMediaTags, path, tag);
      }
      const libraryKeys = new Set(nextMediaLibraryPaths.map(pathKey));
      for (const path of mediaLibraryPathsRef.current) {
        if (remainingPaths.has(pathKey(path)) && !libraryKeys.has(pathKey(path))) {
          nextMediaLibraryPaths.push(path);
          libraryKeys.add(pathKey(path));
        }
      }
    }
    store.setMediaTags(nextMediaTags);
    setMediaLibraryPaths(nextMediaLibraryPaths);
    mediaLibraryPathsRef.current = nextMediaLibraryPaths;
    setDismissedMissingMediaSignature(partiallyApplied ? '' : buildRelinkSignature(collectMissingMedia(nextProject, pathAudit)));
    if (saveAfter) {
      await handleSaveProject({
        projectOverride: nextProject,
        mediaTagsOverride: nextMediaTags,
        mediaLibraryPathsOverride: nextMediaLibraryPaths,
      });
    }
  }, [
    advancedAuthoring,
    handleSaveProject,
    mediaLibraryPathsRef,
    pathAudit,
    setMediaLibraryPaths,
    store,
  ]);

  return {
    missingMedia,
    missingMediaSignature,
    dismissedMissingMediaSignature,
    setDismissedMissingMediaSignature,
    handleApplyMissingMediaRelinks,
  };
}

sources.src/hooks/useProjectMediaDirectory.js:
import { useTreeTranslation } from "../i18n/useTreeTranslation.jsx";
import { presentTree } from "../i18n/treePresentation.js";
import { useEffect, useState } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { useProjectContext } from '../store/ProjectContext';
import { joinPath } from '../utils/fileUtils';

// Display the backend's collision resolution without creating folders or markers.
export function useProjectMediaDirectoryValue(category, fallback = null) {
  const { mediaStorage } = useProjectContext();
  const context = mediaStorage ?? fallback;
  const root = context?.root ?? '';
  const workId = context?.storage?.workId;
  const folder = context?.storage?.folder;
  const ephemeral = context?.ephemeral;
  const key = JSON.stringify([root, workId, folder, ephemeral, category]);
  const [resolved, setResolved] = useState(null);
  useEffect(() => {
    let cancelled = false;
    if (!root || ephemeral || !workId) return undefined;
    invoke('resolve_project_folder', { root, folder, workId, create: false })
      .then(name => { if (!cancelled) setResolved({ key, value: joinPath(root, category, name) }); })
      .catch(() => { if (!cancelled) setResolved({ key, value: { key: "tree:directory.destination.failed" } }); });
    return () => { cancelled = true; };
  }, [root, workId, folder, ephemeral, category, key]);
  if (!root) return { key: "tree:directory.workspace.pending" };
  if (ephemeral || !workId) return joinPath(root, category);
  return resolved?.key === key ? resolved.value : { key: "tree:directory.destination.pending" };
}

export function useProjectMediaDirectory(category, fallback = null) {
  useTreeTranslation();
  return presentTree(useProjectMediaDirectoryValue(category, fallback));
}

sources.src/hooks/useSessionMediaTriage.js:
import { presentUserMessage } from '../i18n/userMessage.js';
import { useCallback, useRef, useState } from 'react';
import { collectSessionOnlyMedia, applySessionMediaTriage } from '../store/sessionMediaTriage';
import { copyMediaToWorkspace } from '../store/projectIO';
import { FICHIERS_IMPORTES } from '../store/workspaceDirs';
import { pathKey } from '../utils/fileUtils';
import { logger } from '../utils/logger';

/**
 * Tri des médias de session à la promotion.
 *
 * `triageSessionMedia({ project, sessionDir, targetWorkspaceDir, mediaStorage, transferCopies })`
 * - re-pointe bibliothèque et tags vers les fichiers déjà copiés par le
 *   transfert des médias référencés (`transferCopies`, pas de re-copie) ;
 * - détecte les orphelins restants (bibliothèque + clés de tags dans la
 *   session, non référencés) et propose le tri à l'utilisateur (modale) ;
 * - copie les conservés dans leur catégorie d’origine et le dossier projet
 *   capturés par la sauvegarde (origine externe → fichiers-importes), avec reprise : en cas
 *   d'échec, dialogue « Réessayer / Abandonner ces fichiers » jusqu'à
 *   résolution explicite — aucun fichier ne reste dans le dossier temporaire
 *   (purgé sous 24 h) sans décision.
 * Retourne `{ changed, mediaLibraryPaths?, mediaTags? }`.
 */
export function useSessionMediaTriage({ store, mediaLibraryPathsRef, setMediaLibraryPaths, showChoiceDialog }) {
  const [triageRequest, setTriageRequest] = useState(null); // null | { items, resolve }
  const liveStoreRef = useRef(store);
  liveStoreRef.current = store;

  const triageSessionMedia = useCallback(async ({
    project,
    sessionDir,
    targetWorkspaceDir,
    mediaStorage = null,
    transferCopies = [],
    isSessionCurrent = () => true,
  }) => {
    if (!isSessionCurrent()) return { changed: false };
    const replacements = new Map();
    for (const copy of transferCopies) {
      if (copy?.from && copy?.to) replacements.set(pathKey(copy.from), copy.to);
    }

    const items = collectSessionOnlyMedia({
      project,
      mediaLibraryPaths: mediaLibraryPathsRef.current,
      mediaTags: liveStoreRef.current.mediaTags,
      sessionDir,
      excludeKeys: replacements,
    });

    const droppedPaths = [];
    if (items.length > 0) {
      const choice = await new Promise((resolve) => setTriageRequest({ items, resolve }));
      setTriageRequest(null);
      if (!isSessionCurrent()) return { changed: false };

      const keptKeys = new Set(choice.keptPaths.map((path) => pathKey(path)));
      for (const item of items) {
        if (!keptKeys.has(pathKey(item.path))) droppedPaths.push(item.path);
      }

      let pending = choice.keptPaths;
      while (pending.length > 0) {
        const failed = [];
        for (const path of pending) {
          if (!isSessionCurrent()) return { changed: false };
          if (replacements.has(pathKey(path))) continue;
          try {
            const artifactCopies = [];
            const dest = await copyMediaToWorkspace(
              path,
              targetWorkspaceDir,
              FICHIERS_IMPORTES,
              { ...(mediaStorage ?? { root: targetWorkspaceDir, storage: project.storage, ephemeral: false }), sessionRoot: sessionDir },
              { artifactCopies },
            );
            replacements.set(pathKey(path), dest);
            for (const copy of artifactCopies) {
              replacements.set(pathKey(copy.from), copy.to);
            }
          } catch (error) {
            failed.push({ path, error: presentUserMessage(error).message });
          }
        }
        if (!isSessionCurrent()) return { changed: false };
        if (failed.length === 0) break;
        logger.error(`session:triage-copy-errors count=${failed.length}`);
        const details = failed.slice(0, 5).map((item) => `• ${item.path}\n  ${item.error}`).join('\n');
        const action = await showChoiceDialog({
          title: 'Copie incomplète',
          message: 'Certains médias conservés n\'ont pas pu être copiés :\n\n'
            + details
            + '\n\nRéessayer, ou les abandonner (ils seront supprimés avec le dossier temporaire de session) ?',
          variant: 'warning',
          cancelValue: 'retry',
          actions: [
            { value: 'drop', label: 'Abandonner ces fichiers', kind: 'danger-outline' },
            { value: 'retry', label: 'Réessayer', kind: 'primary', autoFocus: true },
          ],
        });
        if (action === 'drop') {
          droppedPaths.push(...failed.map((item) => item.path));
          break;
        }
        pending = failed.map((item) => item.path);
      }
    }

    if (!isSessionCurrent()
      || (replacements.size === 0 && droppedPaths.length === 0)) return { changed: false };

    const next = applySessionMediaTriage({
      mediaLibraryPaths: mediaLibraryPathsRef.current,
      mediaTags: liveStoreRef.current.mediaTags,
      replacements,
      droppedPaths,
    });
    const changed = droppedPaths.length > 0
      || JSON.stringify(next.mediaLibraryPaths) !== JSON.stringify(mediaLibraryPathsRef.current)
      || JSON.stringify(next.mediaTags) !== JSON.stringify(liveStoreRef.current.mediaTags);
    if (!changed) return { changed: false };

    liveStoreRef.current.setMediaTags(next.mediaTags);
    setMediaLibraryPaths(next.mediaLibraryPaths);
    mediaLibraryPathsRef.current = next.mediaLibraryPaths;
    logger.info(`session:triage rekeyed=${replacements.size} dropped=${droppedPaths.length}`);

    return {
      changed: true,
      mediaLibraryPaths: next.mediaLibraryPaths,
      mediaTags: next.mediaTags,
      replacements,
    };
  }, [mediaLibraryPathsRef, setMediaLibraryPaths, showChoiceDialog, store]);

  return { triageSessionMedia, triageRequest };
}

