// Les outils média, des deux côtés.
//
// Quatre outils — podcast, YouTube, micro, voix de synthèse — produisent un
// fichier audio. Ce que ce fichier **est** ne dépend pas de l'éditeur ouvert ;
// seuls son point d'arrivée et le voisinage qu'on lui offre en dépendent.
//
// Ce module tient ces deux règles, et rien d'autre : elles sont la seule chose
// qui diffère entre les deux éditeurs, et les écrire deux fois les ferait
// diverger comme ont divergé deux jeux de réglages audio.
//
// **Le point d'arrivée.** Côté Libre, le son produit devient une histoire dans
// le dossier visé — comportement historique, qui ne se renégocie pas. Côté
// graphe, il entre dans la bibliothèque de médias, et l'auteur le pose ensuite
// sur l'Écran de son choix par le geste de dépôt. Faire atterrir un son
// directement sur un Écran créerait une modification du document que personne
// n'a demandée ; la bibliothèque est le point d'arrivée neutre, et le dépôt
// reste un geste, annulable et historisé.
//
// **Ce que la barre montre.** Trois de ses actions visent un dossier de
// l'arbre : ajouter une histoire, créer un dossier, importer un dossier. Sur un
// document de graphe, il n'y a pas d'arbre, donc pas d'objet. Elles n'y sont
// pas montrées — ni telles quelles, ni déguisées. L'import de fichiers y prend
// la seule forme qui ait un sens : l'entrée dans la bibliothèque.

import { WORKSPACE_MODE_ADVANCED } from './projectWorkState.js';

export const MEDIA_LANDING_TREE = 'tree';
export const MEDIA_LANDING_LIBRARY = 'library';

/** Où atterrit le son produit par un outil, selon l'éditeur ouvert. */
export function mediaToolLanding(workspaceMode) {
  return workspaceMode === WORKSPACE_MODE_ADVANCED ? MEDIA_LANDING_LIBRARY : MEDIA_LANDING_TREE;
}

// Les actions de la barre. Les identifiants sont ceux que la barre peint ;
// l'ordre du côté Libre est celui d'origine, au bouton près.
export const MEDIA_TOOL_ACTIONS = Object.freeze({
  IMPORT_STORY: 'import-story',
  ADD_FOLDER: 'add-folder',
  IMPORT_FOLDER: 'import-folder',
  IMPORT_MEDIA: 'import-media',
  IMPORT_PODCAST: 'import-podcast',
  IMPORT_YOUTUBE: 'import-youtube',
  RECORD: 'record',
  GENERATE_TTS: 'generate-tts',
  SIMULATOR: 'simulator',
});

const TREE_BAR = Object.freeze([
  MEDIA_TOOL_ACTIONS.IMPORT_STORY,
  MEDIA_TOOL_ACTIONS.ADD_FOLDER,
  MEDIA_TOOL_ACTIONS.IMPORT_FOLDER,
  MEDIA_TOOL_ACTIONS.IMPORT_PODCAST,
  MEDIA_TOOL_ACTIONS.IMPORT_YOUTUBE,
  MEDIA_TOOL_ACTIONS.RECORD,
  MEDIA_TOOL_ACTIONS.GENERATE_TTS,
  MEDIA_TOOL_ACTIONS.SIMULATOR,
]);

// Côté graphe, ces actions vivent dans le L ancré au canvas. L'écoute y garde
// la même petite icône que dans le Libre ; la liste des nœuds garde sa recherche
// locale, sans recopier les outils de production de médias.
const GRAPH_BAR = Object.freeze([
  MEDIA_TOOL_ACTIONS.IMPORT_MEDIA,
  MEDIA_TOOL_ACTIONS.IMPORT_PODCAST,
  MEDIA_TOOL_ACTIONS.IMPORT_YOUTUBE,
  MEDIA_TOOL_ACTIONS.RECORD,
  MEDIA_TOOL_ACTIONS.GENERATE_TTS,
  MEDIA_TOOL_ACTIONS.SIMULATOR,
]);

/** Les actions qui ont un objet dans cet éditeur, dans leur ordre d'apparition. */
export function mediaToolActionIds(workspaceMode) {
  return workspaceMode === WORKSPACE_MODE_ADVANCED ? GRAPH_BAR : TREE_BAR;
}

/**
 * Le plan d'atterrissage d'un média produit — **une valeur, pas un effet**.
 *
 * Écrit ici une seule fois pour les quatre outils : chacun appelle son moteur à
 * sa façon, mais aucun ne décide seul où son résultat atterrit. C'est aussi ce
 * qui rend la contrainte vérifiable sans monter d'écran : un plan de graphe ne
 * porte jamais d'identifiant de dossier, donc ne peut pas créer d'Écran.
 *
 * `imagePath` est la vignette qu'un épisode ou une vidéo amène avec lui. Côté
 * Libre elle devient l'image de l'histoire créée ; côté graphe elle entre dans
 * la bibliothèque à côté de l'audio, sans être attachée à quoi que ce soit.
 */
export function planProducedMediaLanding({
  landing,
  audioPath,
  imagePath = null,
  targetMenuId = null,
}) {
  if (!audioPath) return null;
  if (landing === MEDIA_LANDING_LIBRARY) {
    return Object.freeze({
      kind: MEDIA_LANDING_LIBRARY,
      paths: Object.freeze([audioPath, imagePath].filter(Boolean)),
    });
  }
  return Object.freeze({
    kind: MEDIA_LANDING_TREE,
    menuId: targetMenuId ?? null,
    audioPath,
    imagePath: imagePath ?? null,
  });
}

sources.src/store/missingMediaRelink.js:
import { basename, joinPath, pathKey } from '../utils/fileUtils.js';
import { getIntlLocale } from '../i18n/language.js';
import { walkProjectMediaReferences } from './projectModel/index.js';
import { readMediaBindings } from './projectModel/mediaBindings.js';
import { MANAGED_PROJECT_DIRS } from './workspaceDirs.js';

function hasPath(path) {
  return typeof path === 'string' && path.trim().length > 0;
}

function replacementForPath(path, replacements) {
  if (!hasPath(path)) return null;
  const key = pathKey(path);
  return replacements.get(key) ?? null;
}

export function mediaKindFromPath(path) {
  const ext = String(path || '').toLowerCase().replace(/^.*\./, '');
  if (['mp3', 'ogg', 'wav', 'm4a', 'webm', 'flac', 'aac'].includes(ext)) return 'audio';
  if (['png', 'jpg', 'jpeg', 'webp', 'bmp', 'gif'].includes(ext)) return 'image';
  if (['zip', '7z'].includes(ext)) return 'archive';
  return 'media';
}

export function collectMissingMedia(project, statusByPath = {}) {
  const byPath = new Map();
  for (const ref of walkProjectMediaReferences(project)) {
    if (statusByPath?.[ref.path] !== false) continue;
    const key = pathKey(ref.path);
    const current = byPath.get(key) ?? {
      path: ref.path,
      fileName: basename(ref.path) || ref.path,
      kind: mediaKindFromPath(ref.path),
      labels: [],
      count: 0,
    };
    current.count += 1;
    if (ref.label && !current.labels.includes(ref.label)) current.labels.push(ref.label);
    byPath.set(key, current);
  }
  return [...byPath.values()].sort((a, b) => a.fileName.localeCompare(b.fileName, getIntlLocale()));
}

function normalizeReplacementMap(replacements = {}) {
  if (replacements instanceof Map) {
    return new Map(
      [...replacements.entries()]
        .filter(([, next]) => hasPath(next))
        .map(([previous, next]) => [pathKey(previous), next]),
    );
  }
  return new Map(
    Object.entries(replacements)
      .filter(([, next]) => hasPath(next))
      .map(([previous, next]) => [pathKey(previous), next]),
  );
}

export function relinkProjectMedia(project, replacements = {}) {
  const map = normalizeReplacementMap(replacements);
  if (map.size === 0) return project;
  const next = structuredClone(project);
  for (const ref of walkProjectMediaReferences(next)) {
    const replacement = replacementForPath(ref.path, map);
    if (replacement) ref.obj[ref.key] = replacement;
  }
  return next;
}

// La même reliaison, côté projet graphe, **sous forme de plan et non de
// mutation**. `relinkProjectMedia` réécrit `binding.path` dans une copie du
// projet : c'est la mutation directe que le mouvement 1 interdit pour un
// document d'auteur, et elle n'entrerait dans aucun historique. Un plan se
// convertit en gestes `repoint-media`, qui sont annulables.
//
// La correspondance se fait par **chemin**, parce que c'est ce qu'un fichier
// déplacé change, et rend l'`assetRef`, parce que c'est par elle qu'une liaison
// est adressée. Une référence citée par le document mais sans liaison n'a pas
// de chemin manquant à relier : elle n'entre pas dans un plan.
//
// Un pas par liaison touchée : une même référence employée par plusieurs Écrans
// ne produit qu'un seul pas, puisque le geste repointe la référence entière.
export function planAdvancedRelink(project, replacements = {}) {
  const map = normalizeReplacementMap(replacements);
  if (map.size === 0) return [];
  const plan = [];
  const seen = new Set();
  for (const binding of readMediaBindings(project)) {
    const assetRef = binding?.assetRef;
    if (typeof assetRef !== 'string' || assetRef === '' || seen.has(assetRef)) continue;
    const replacement = replacementForPath(binding?.path, map);
    if (!replacement) continue;
    seen.add(assetRef);
    plan.push({ assetRef, path: replacement, previousPath: binding.path });
  }
  return plan;
}

export function relinkMediaTags(mediaTags = {}, replacements = {}) {
  const map = normalizeReplacementMap(replacements);
  if (map.size === 0 || !mediaTags || typeof mediaTags !== 'object') return mediaTags ?? {};
  const next = {};
  for (const [tagPath, tags] of Object.entries(mediaTags)) {
    const replacement = replacementForPath(tagPath, map);
    const nextPath = replacement ?? tagPath;
    next[nextPath] = [...new Set([...(next[nextPath] ?? []), ...tags])];
  }
  return next;
}

export function relinkMediaLibraryPaths(paths = [], replacements = {}) {
  const map = normalizeReplacementMap(replacements);
  if (map.size === 0 || !Array.isArray(paths)) return paths ?? [];
  return paths.map((path) => replacementForPath(path, map) ?? path);
}

export function candidatePathsForRelinkRoot(missingPath, selectedRoot) {
  if (!hasPath(missingPath) || !hasPath(selectedRoot)) return [];
  const normalized = pathKey(missingPath);
  const candidates = [];
  for (const dirName of MANAGED_PROJECT_DIRS) {
    const marker = `/${dirName}/`;
    const markerIndex = normalized.lastIndexOf(marker);
    if (markerIndex >= 0) {
      candidates.push(joinPath(selectedRoot, normalized.slice(markerIndex + 1)));
    }
  }
  candidates.push(joinPath(selectedRoot, basename(missingPath)));
  const seen = new Set();
  return candidates.filter((candidate) => {
    const key = pathKey(candidate);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

// Lignes de la boîte « Médias introuvables » après un nouvel audit. Un fichier
// déjà relié, ou en attente d'un choix entre plusieurs correspondances, garde
// son état tant qu'il manque encore ; un fichier revenu à sa place quitte la
// liste, un fichier qui vient de disparaître y entre. Sans cela, chaque
// relecture du disque effaçait le travail de l'auteur dans la boîte.
export function refreshRelinkRows(rows = [], missingMedia = []) {
  const previousByPath = new Map(rows.map((row) => [pathKey(row.path), row]));
  return missingMedia.map((item) => {
    const previous = previousByPath.get(pathKey(item.path));
    return {
      ...item,
      status: previous?.status ?? 'missing',
      replacementPath: previous?.replacementPath ?? '',
      matches: previous?.matches ?? [],
    };
  });
}

// La règle d'ouverture de la proposition de relier, sortie du hook pour être
// éprouvable sans monter React.
//
// Elle ne demande pas d'arbre : `collectMissingMedia` parcourt aussi
// les liaisons d'un projet graphe : la proposition s'ouvre dès que la liste existe.
//
// Les trois autres conditions sont inchangées et ont chacune leur raison : sans
// chemin d'enregistrement, on n'a pas de dossier de référence pour proposer des
// candidats ; pendant un audit, la liste n'est pas encore stable ; et une liste
// déjà rejetée ne se represente pas tant qu'elle n'a pas changé.
//
// L'audit en cours ne retient que l'**ouverture** : une proposition déjà
// ouverte (`proposalOpen`) le reste pendant qu'un audit est relancé. Le retour
// d'une boîte native — choisir un dossier, un fichier — redonne le focus à la
// fenêtre, ce focus relance l'audit, et fermer alors la proposition démontait
// la boîte avec les fichiers que l'auteur venait de relier.
export function shouldProposeMissingMediaRelink({
  projectOpen = false,
  savePath = null,
  pathAuditPending = false,
  proposalOpen = false,
  missingMedia = [],
  missingMediaSignature = '',
  dismissedMissingMediaSignature = '',
} = {}) {
  return projectOpen
    && !!savePath
    && (!pathAuditPending || proposalOpen)
    && missingMedia.length > 0
    && missingMediaSignature !== dismissedMissingMediaSignature;
}

export function buildRelinkSignature(missingMedia = []) {
  return missingMedia.map((item) => pathKey(item.path)).sort().join('|');
}

sources.src/store/projectMediaOutput.js:
import { joinPath } from '../utils/fileUtils.js';
import { PROJECT_MEDIA_CATEGORIES } from './projectStorage.js';

async function invokeTauri(command, args) {
  const { invoke } = await import('@tauri-apps/api/core');
  return invoke(command, args);
}
const active = new Map();
const locks = new Map();
const finalized = new Map();
const jobOutputs = new Map();

export function isProjectMediaOutputBusy(workId) { return (active.get(workId) ?? 0) > 0; }
export function lockProjectMediaStorage(workId, { allowActive = false } = {}) {
  if ((!allowActive && isProjectMediaOutputBusy(workId)) || locks.has(workId)) return null;
  const token = {};
  locks.set(workId, token);
  const release = () => { if (locks.get(workId) === token) locks.delete(workId); };
  release.token = token;
  return release;
}
export function publishProjectMediaStorage(storage) { finalized.set(storage.workId, storage); }

// Acquire before the first await; callers hold this reservation for the entire
// write, including queued jobs. The root and work identity never follow renders.
export function beginProjectMediaOutput(context, { invokeCommand = invokeTauri } = {}) {
  const root = String(context?.root ?? '').trim();
  const storage = finalized.get(context?.storage?.workId) ?? context?.storage;
  const workId = storage?.workId;
  const ephemeral = context?.ephemeral;
  if (!root) throw new Error('Aucun emplacement de travail pour ce média.');
  if (workId && locks.has(workId) && locks.get(workId) !== context?.saveToken) throw new Error('Le projet est en cours de rangement. Réessaie après son enregistrement.');
  if (workId) active.set(workId, (active.get(workId) ?? 0) + 1);
  let released = false;
  let resolved = null;
  const destination = () => {
    if (!resolved) {
      resolved = !ephemeral && storage
        ? invokeCommand('resolve_project_folder', { root, folder: storage.folder, workId, create: true })
          .then((folder) => ({ folder, workId }))
        : Promise.resolve(null);
    }
    return resolved;
  };
  return {
    async directory(category) {
      if (!PROJECT_MEDIA_CATEGORIES.includes(category)) throw new Error('Catégorie média invalide.');
      const projectDestination = await destination();
      return joinPath(root, category, ...(projectDestination ? [projectDestination.folder] : []));
    },
    async arguments() { return { workspaceDir: root, projectDestination: await destination() }; },
    release() {
      if (released) return;
      released = true;
      if (workId) { const count = active.get(workId) - 1; if (count) active.set(workId, count); else active.delete(workId); }
    },
  };
}

export async function withProjectMediaOutput(context, run, options) {
  const output = beginProjectMediaOutput(context, options);
  try { return await run(output); } finally { output.release(); }
}

export async function captureProjectMediaJob(context) {
  const output = beginProjectMediaOutput(context);
  try {
    const args = await output.arguments();
    const outputId = crypto.randomUUID();
    jobOutputs.set(outputId, output);
    return { ...args, outputId, workId: context?.storage?.workId };
  } catch (error) { output.release(); throw error; }
}
export function releaseProjectMediaJob(job) {
  const id = job?.mediaOutput?.outputId;
  jobOutputs.get(id)?.release(); jobOutputs.delete(id);
}

